-- ============================================================================
-- الأخبار (News) — Full CMS seed
-- Page slug '/news' — the public page at /News/news.html
-- resolves this slug via supabase/news-content.js (dedicated loader).
-- NON-DESTRUCTIVE: UPDATE existing + INSERT missing. Safe to re-run.
-- Content extracted verbatim from /News/news.html (real content: 7 sections,
-- 12 news items, 8 categories). The page has NO content images (SVG
-- placeholder icons) so each of the 13 image fields is seeded EMPTY ('').
-- Every news item link is '#' in the source — preserved as-is.
-- ONLY touches this page.
-- ============================================================================

DO $$
DECLARE
  v_pid UUID;
BEGIN
  SELECT id INTO v_pid FROM pages WHERE slug = '/news' LIMIT 1;
  IF v_pid IS NULL THEN
    INSERT INTO pages (title, slug, status) VALUES ('الأخبار', '/news', 'published') RETURNING id INTO v_pid;
  END IF;
  RAISE NOTICE 'page_id: %', v_pid;

  -- 1. HERO  (#nwHero)
  UPDATE page_sections SET section_type = 'hero',
    content = '{"heading":"آخر الأخبار","headingEm":"الأخبار","subheading":"بوابة الأخبار","description":"تابع آخر أخبار الجمعية المغربية لهواة البحث والاستكشاف، والأنشطة، والفعاليات، والشراكات، وكل جديد.","backgroundImage":"","buttons":[{"id":"btn-news-hero-latest","label":"أحدث الأخبار","url":"#nwLatest","variant":"primary"},{"id":"btn-news-hero-contact","label":"تواصل معنا","url":"../contact.html","variant":"secondary"}]}'::jsonb,
    settings='{}'::jsonb, styles='{}'::jsonb
    WHERE page_id = v_pid AND sort_order = 1;
  IF NOT FOUND THEN INSERT INTO page_sections (id, page_id, section_type, visible, sort_order, content, settings, styles) VALUES (gen_random_uuid(), v_pid, 'hero', TRUE, 1, '{"heading":"آخر الأخبار","headingEm":"الأخبار","subheading":"بوابة الأخبار","description":"تابع آخر أخبار الجمعية المغربية لهواة البحث والاستكشاف، والأنشطة، والفعاليات، والشراكات، وكل جديد.","backgroundImage":"","buttons":[{"id":"btn-news-hero-latest","label":"أحدث الأخبار","url":"#nwLatest","variant":"primary"},{"id":"btn-news-hero-contact","label":"تواصل معنا","url":"../contact.html","variant":"secondary"}]}'::jsonb, '{}'::jsonb, '{}'::jsonb); END IF;

  -- 2. FEATURED NEWS  (#nwFeatured)
  UPDATE page_sections SET section_type = 'custom',
    content = '{"_renderer":"nwFeatured","eyebrow":"خبر مميز","heading":"أبرز الأخبار"}'::jsonb,
    settings='{}'::jsonb, styles='{}'::jsonb
    WHERE page_id = v_pid AND sort_order = 2;
  IF NOT FOUND THEN INSERT INTO page_sections (id, page_id, section_type, visible, sort_order, content, settings, styles) VALUES (gen_random_uuid(), v_pid, 'custom', TRUE, 2, '{"_renderer":"nwFeatured","eyebrow":"خبر مميز","heading":"أبرز الأخبار"}'::jsonb, '{}'::jsonb, '{}'::jsonb); END IF;

  -- 3. LATEST NEWS  (#nwLatest) — 12 news items
  UPDATE page_sections SET section_type = 'custom',
    content = '{"_renderer":"nwGrid","eyebrow":"أحدث الأخبار","heading":"آخر ما نشر","description":"تصفح أحدث أخبار ومقالات الجمعية المغربية لهواة البحث والاستكشاف.","items":[{"category":"activities","catLabel":"أنشطة","featured":true,"title":"خرجة استكشافية ناجحة إلى جبال الأطلس الكبير","summary":"نظمت الجمعية خرجة استكشافية إلى منطقة إمليل بجبال الأطلس الكبير بمشاركة 45 عضواً، تم خلالها استكشاف المناظر الطبيعية والتعرف على التنوع البيولوجي.","author":"فريق التحرير","date":"2026-08-05","image":"","linkUrl":"#","linkLabel":"اقرأ المزيد"},{"category":"partnerships","catLabel":"شراكات","featured":false,"title":"توقيع اتفاقية شراكة مع ASTROMET","summary":"وقعت الجمعية اتفاقية شراكة استراتيجية مع شركة ASTROMET المتخصصة في التنقيب والاستكشاف المعدني بالمغرب.","author":"لجنة الشراكات","date":"2026-07-28","image":"","linkUrl":"#","linkLabel":"اقرأ المزيد"},{"category":"competitions","catLabel":"مسابقات","featured":false,"title":"إعلان نتائج المسابقة الوطنية للكشف عن المعادن","summary":"اختتمت الجمعية المسابقة الوطنية للكشف عن المعادن بمشاركة 120 متسابقاً من مختلف جهات المملكة.","author":"لجنة المسابقات","date":"2026-07-20","image":"","linkUrl":"#","linkLabel":"اقرأ المزيد"},{"category":"outings","catLabel":"خرجات","featured":false,"title":"رحلة استكشافية إلى مغارة فريواطو بتازة","summary":"نظمت الجمعية رحلة استكشافية إلى مغارة فريواطو، إحدى أعمق المغارات في إفريقيا، مع فريق متخصص في علم الكهوف.","author":"فريق التحرير","date":"2026-07-15","image":"","linkUrl":"#","linkLabel":"اقرأ المزيد"},{"category":"environmental","catLabel":"حملات بيئية","featured":false,"title":"حملة تنظيف شاطئ أكادير تجمع 200 متطوع","summary":"نجحت الحملة البيئية التي نظمتها الجمعية في جمع أكثر من 2 طن من النفايات بشاطئ أكادير بمشاركة 200 متطوع.","author":"لجنة البيئة","date":"2026-07-10","image":"","linkUrl":"#","linkLabel":"اقرأ المزيد"},{"category":"exhibitions","catLabel":"معارض","featured":false,"title":"المعرض الجهوي للمستكشفين يحقق نجاحاً كبيراً","summary":"اختتم المعرض الجهوي للمستكشفين الذي نظمته الجمعية بمشاركة 30 عارضاً وعرض لأحدث الاكتشافات والأجهزة.","author":"فريق التحرير","date":"2026-07-03","image":"","linkUrl":"#","linkLabel":"اقرأ المزيد"},{"category":"association","catLabel":"الجمعية","featured":false,"title":"انعقاد الجمع العام السنوي للجمعية","summary":"عقدت الجمعية جمعها العام السنوي بحضور ممثلي الفروع الجهوية، وتمت مناقشة التقريرين الأدبي والمالي وانتخاب المكتب الجديد.","author":"الأمانة العامة","date":"2026-06-25","image":"","linkUrl":"#","linkLabel":"اقرأ المزيد"},{"category":"announcements","catLabel":"إعلانات","featured":false,"title":"فتح باب الانخراط للموسم الجديد 2026-2027","summary":"تعلن الجمعية عن فتح باب الانخراط للموسم الجديد، ويمكن للراغبين التسجيل عبر الموقع الإلكتروني أو في المقر.","author":"لجنة العضوية","date":"2026-06-18","image":"","linkUrl":"#","linkLabel":"اقرأ المزيد"},{"category":"activities","catLabel":"أنشطة","featured":false,"title":"دورة تكوينية في الملاحة البرية وقراءة الخرائط","summary":"نظمت الجمعية دورة تكوينية في الملاحة البرية لفائدة 35 عضواً، تضمنت دروساً نظرية وتطبيقات ميدانية.","author":"لجنة التكوين","date":"2026-06-10","image":"","linkUrl":"#","linkLabel":"اقرأ المزيد"},{"category":"partnerships","catLabel":"شراكات","featured":false,"title":"اتفاقية تعاون مع منظمة OMSDS للتنمية الاجتماعية","summary":"وقعت الجمعية اتفاقية تعاون مع منظمة OMSDS للتنمية الاجتماعية والتضامن لدعم الأنشطة الاجتماعية والتطوعية.","author":"لجنة الشراكات","date":"2026-06-01","image":"","linkUrl":"#","linkLabel":"اقرأ المزيد"},{"category":"environmental","catLabel":"حملات بيئية","featured":false,"title":"حملة تشجير غابة المعمورة بمشاركة 150 متطوعاً","summary":"نظمت الجمعية حملة تشجير بغابة المعمورة تم فيها غرس 1000 شجرة بمشاركة السلطات المحلية والمدارس.","author":"لجنة البيئة","date":"2026-05-22","image":"","linkUrl":"#","linkLabel":"اقرأ المزيد"},{"category":"association","catLabel":"الجمعية","featured":false,"title":"افتتاح فرع جديد للجمعية بجهة طنجة","summary":"افتتحت الجمعية فرعاً جهوياً جديداً بجهة طنجة - تطوان - الحسيمة لتوسيع نطاق أنشطتها في شمال المملكة.","author":"المكتب المركزي","date":"2026-05-15","image":"","linkUrl":"#","linkLabel":"اقرأ المزيد"}]}'::jsonb,
    settings='{}'::jsonb, styles='{}'::jsonb
    WHERE page_id = v_pid AND sort_order = 3;
  IF NOT FOUND THEN INSERT INTO page_sections (id, page_id, section_type, visible, sort_order, content, settings, styles) VALUES (gen_random_uuid(), v_pid, 'custom', TRUE, 3, '{"_renderer":"nwGrid","eyebrow":"أحدث الأخبار","heading":"آخر ما نشر","description":"تصفح أحدث أخبار ومقالات الجمعية المغربية لهواة البحث والاستكشاف.","items":[{"category":"activities","catLabel":"أنشطة","featured":true,"title":"خرجة استكشافية ناجحة إلى جبال الأطلس الكبير","summary":"نظمت الجمعية خرجة استكشافية إلى منطقة إمليل بجبال الأطلس الكبير بمشاركة 45 عضواً، تم خلالها استكشاف المناظر الطبيعية والتعرف على التنوع البيولوجي.","author":"فريق التحرير","date":"2026-08-05","image":"","linkUrl":"#","linkLabel":"اقرأ المزيد"},{"category":"partnerships","catLabel":"شراكات","featured":false,"title":"توقيع اتفاقية شراكة مع ASTROMET","summary":"وقعت الجمعية اتفاقية شراكة استراتيجية مع شركة ASTROMET المتخصصة في التنقيب والاستكشاف المعدني بالمغرب.","author":"لجنة الشراكات","date":"2026-07-28","image":"","linkUrl":"#","linkLabel":"اقرأ المزيد"},{"category":"competitions","catLabel":"مسابقات","featured":false,"title":"إعلان نتائج المسابقة الوطنية للكشف عن المعادن","summary":"اختتمت الجمعية المسابقة الوطنية للكشف عن المعادن بمشاركة 120 متسابقاً من مختلف جهات المملكة.","author":"لجنة المسابقات","date":"2026-07-20","image":"","linkUrl":"#","linkLabel":"اقرأ المزيد"},{"category":"outings","catLabel":"خرجات","featured":false,"title":"رحلة استكشافية إلى مغارة فريواطو بتازة","summary":"نظمت الجمعية رحلة استكشافية إلى مغارة فريواطو، إحدى أعمق المغارات في إفريقيا، مع فريق متخصص في علم الكهوف.","author":"فريق التحرير","date":"2026-07-15","image":"","linkUrl":"#","linkLabel":"اقرأ المزيد"},{"category":"environmental","catLabel":"حملات بيئية","featured":false,"title":"حملة تنظيف شاطئ أكادير تجمع 200 متطوع","summary":"نجحت الحملة البيئية التي نظمتها الجمعية في جمع أكثر من 2 طن من النفايات بشاطئ أكادير بمشاركة 200 متطوع.","author":"لجنة البيئة","date":"2026-07-10","image":"","linkUrl":"#","linkLabel":"اقرأ المزيد"},{"category":"exhibitions","catLabel":"معارض","featured":false,"title":"المعرض الجهوي للمستكشفين يحقق نجاحاً كبيراً","summary":"اختتم المعرض الجهوي للمستكشفين الذي نظمته الجمعية بمشاركة 30 عارضاً وعرض لأحدث الاكتشافات والأجهزة.","author":"فريق التحرير","date":"2026-07-03","image":"","linkUrl":"#","linkLabel":"اقرأ المزيد"},{"category":"association","catLabel":"الجمعية","featured":false,"title":"انعقاد الجمع العام السنوي للجمعية","summary":"عقدت الجمعية جمعها العام السنوي بحضور ممثلي الفروع الجهوية، وتمت مناقشة التقريرين الأدبي والمالي وانتخاب المكتب الجديد.","author":"الأمانة العامة","date":"2026-06-25","image":"","linkUrl":"#","linkLabel":"اقرأ المزيد"},{"category":"announcements","catLabel":"إعلانات","featured":false,"title":"فتح باب الانخراط للموسم الجديد 2026-2027","summary":"تعلن الجمعية عن فتح باب الانخراط للموسم الجديد، ويمكن للراغبين التسجيل عبر الموقع الإلكتروني أو في المقر.","author":"لجنة العضوية","date":"2026-06-18","image":"","linkUrl":"#","linkLabel":"اقرأ المزيد"},{"category":"activities","catLabel":"أنشطة","featured":false,"title":"دورة تكوينية في الملاحة البرية وقراءة الخرائط","summary":"نظمت الجمعية دورة تكوينية في الملاحة البرية لفائدة 35 عضواً، تضمنت دروساً نظرية وتطبيقات ميدانية.","author":"لجنة التكوين","date":"2026-06-10","image":"","linkUrl":"#","linkLabel":"اقرأ المزيد"},{"category":"partnerships","catLabel":"شراكات","featured":false,"title":"اتفاقية تعاون مع منظمة OMSDS للتنمية الاجتماعية","summary":"وقعت الجمعية اتفاقية تعاون مع منظمة OMSDS للتنمية الاجتماعية والتضامن لدعم الأنشطة الاجتماعية والتطوعية.","author":"لجنة الشراكات","date":"2026-06-01","image":"","linkUrl":"#","linkLabel":"اقرأ المزيد"},{"category":"environmental","catLabel":"حملات بيئية","featured":false,"title":"حملة تشجير غابة المعمورة بمشاركة 150 متطوعاً","summary":"نظمت الجمعية حملة تشجير بغابة المعمورة تم فيها غرس 1000 شجرة بمشاركة السلطات المحلية والمدارس.","author":"لجنة البيئة","date":"2026-05-22","image":"","linkUrl":"#","linkLabel":"اقرأ المزيد"},{"category":"association","catLabel":"الجمعية","featured":false,"title":"افتتاح فرع جديد للجمعية بجهة طنجة","summary":"افتتحت الجمعية فرعاً جهوياً جديداً بجهة طنجة - تطوان - الحسيمة لتوسيع نطاق أنشطتها في شمال المملكة.","author":"المكتب المركزي","date":"2026-05-15","image":"","linkUrl":"#","linkLabel":"اقرأ المزيد"}]}'::jsonb, '{}'::jsonb, '{}'::jsonb); END IF;

  -- 4. CATEGORIES  (#nwCategories) — 8 categories
  UPDATE page_sections SET section_type = 'custom',
    content = '{"_renderer":"nwCategories","eyebrow":"تصفح حسب الفئة","heading":"فئات الأخبار","description":"اختر الفئة التي تهمك لتصفح الأخبار المتعلقة بها.","categories":[{"id":"activities","label":"أنشطة"},{"id":"partnerships","label":"شراكات"},{"id":"competitions","label":"مسابقات"},{"id":"outings","label":"خرجات"},{"id":"environmental","label":"حملات بيئية"},{"id":"exhibitions","label":"معارض"},{"id":"association","label":"الجمعية"},{"id":"announcements","label":"إعلانات"}]}'::jsonb,
    settings='{}'::jsonb, styles='{}'::jsonb
    WHERE page_id = v_pid AND sort_order = 4;
  IF NOT FOUND THEN INSERT INTO page_sections (id, page_id, section_type, visible, sort_order, content, settings, styles) VALUES (gen_random_uuid(), v_pid, 'custom', TRUE, 4, '{"_renderer":"nwCategories","eyebrow":"تصفح حسب الفئة","heading":"فئات الأخبار","description":"اختر الفئة التي تهمك لتصفح الأخبار المتعلقة بها.","categories":[{"id":"activities","label":"أنشطة"},{"id":"partnerships","label":"شراكات"},{"id":"competitions","label":"مسابقات"},{"id":"outings","label":"خرجات"},{"id":"environmental","label":"حملات بيئية"},{"id":"exhibitions","label":"معارض"},{"id":"association","label":"الجمعية"},{"id":"announcements","label":"إعلانات"}]}'::jsonb, '{}'::jsonb, '{}'::jsonb); END IF;

  -- 5. SEARCH & FILTER  (#nwSearch)
  UPDATE page_sections SET section_type = 'custom',
    content = '{"_renderer":"nwSearch","eyebrow":"بحث متقدم","heading":"ابحث في الأخبار"}'::jsonb,
    settings='{}'::jsonb, styles='{}'::jsonb
    WHERE page_id = v_pid AND sort_order = 5;
  IF NOT FOUND THEN INSERT INTO page_sections (id, page_id, section_type, visible, sort_order, content, settings, styles) VALUES (gen_random_uuid(), v_pid, 'custom', TRUE, 5, '{"_renderer":"nwSearch","eyebrow":"بحث متقدم","heading":"ابحث في الأخبار"}'::jsonb, '{}'::jsonb, '{}'::jsonb); END IF;

  -- 6. NEWSLETTER  (#nwNewsletter)
  UPDATE page_sections SET section_type = 'custom',
    content = '{"_renderer":"nwNewsletter","heading":"اشترك في نشرتنا الإخبارية","description":"توصل بأحدث الأخبار والفعاليات مباشرة على بريدك الإلكتروني.","buttonLabel":"اشترك الآن"}'::jsonb,
    settings='{}'::jsonb, styles='{}'::jsonb
    WHERE page_id = v_pid AND sort_order = 6;
  IF NOT FOUND THEN INSERT INTO page_sections (id, page_id, section_type, visible, sort_order, content, settings, styles) VALUES (gen_random_uuid(), v_pid, 'custom', TRUE, 6, '{"_renderer":"nwNewsletter","heading":"اشترك في نشرتنا الإخبارية","description":"توصل بأحدث الأخبار والفعاليات مباشرة على بريدك الإلكتروني.","buttonLabel":"اشترك الآن"}'::jsonb, '{}'::jsonb, '{}'::jsonb); END IF;

  -- 7. FINAL CTA  (#nwCta)
  UPDATE page_sections SET section_type = 'custom',
    content = '{"_renderer":"nwCta","heading":"ابق على اطلاع بكل جديد.","buttons":[{"id":"btn-news-cta-all","label":"جميع الأخبار","url":"#nwLatest","variant":"primary"},{"id":"btn-news-cta-contact","label":"اتصل بنا","url":"../contact.html","variant":"secondary"}]}'::jsonb,
    settings='{}'::jsonb, styles='{}'::jsonb
    WHERE page_id = v_pid AND sort_order = 7;
  IF NOT FOUND THEN INSERT INTO page_sections (id, page_id, section_type, visible, sort_order, content, settings, styles) VALUES (gen_random_uuid(), v_pid, 'custom', TRUE, 7, '{"_renderer":"nwCta","heading":"ابق على اطلاع بكل جديد.","buttons":[{"id":"btn-news-cta-all","label":"جميع الأخبار","url":"#nwLatest","variant":"primary"},{"id":"btn-news-cta-contact","label":"اتصل بنا","url":"../contact.html","variant":"secondary"}]}'::jsonb, '{}'::jsonb, '{}'::jsonb); END IF;

  RAISE NOTICE 'NEWS: % sections', (SELECT COUNT(*) FROM page_sections WHERE page_id = v_pid);
END $$;
